<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php'; methodOnly('PUT'); $customer=getCurrentCustomer(); if(!$customer)jsonResponse(false,'Customer authentication required.',null,[],401); safeApi(function()use($customer):void{$i=jsonRequest();$name=inputString($i,'name',true);$phone=inputString($i,'phone');if(strlen($name)<2)jsonResponse(false,'A valid name is required.',null,[],422);$db=apiDatabase();$q=$db->prepare('UPDATE customers SET name=:name, phone=:phone WHERE id=:id');$q->execute([':name'=>$name,':phone'=>$phone,':id'=>$customer['id']]);$q=$db->prepare('SELECT id,name,email,phone FROM customers WHERE id=:id');$q->execute([':id'=>$customer['id']]);jsonResponse(true,'Profile updated.',$q->fetch());});
